.sortButton { min-height: var(--control-height-sm); padding: 0 var(--space-3); border: 1px solid var(--border); border-radius: var(--radius-control); background: var(--surface); color: var(--text-secondary); font: inherit; font-size: var(--text-sm); cursor: pointer; }
.sortButton b { color: var(--foreground); font-weight: 500; }
