.thumb::-moz-range-thumb { width: 1.1rem; height: 1.1rem; border: 2px solid var(--accent); border-radius: 50%; background: var(--surface); pointer-events: auto; cursor: grab; }
.thumb:focus-visible::-webkit-slider-thumb { outline: var(--focus-outline-width, 2px) solid var(--focus-outline, var(--accent)); outline-offset: 2px; }
.thumb:focus-visible::-moz-range-thumb { outline: var(--focus-outline-width, 2px) solid var(--focus-outline, var(--accent)); outline-offset: 2px; }
