.sizeFilter { display: flex; flex-wrap: wrap; gap: var(--space-2); }
.chip { min-width: 2.5rem; min-height: var(--control-height-sm); padding: 0 var(--space-3); border: 1px solid var(--border); border-radius: var(--radius-control); background: var(--surface); color: var(--foreground); font: inherit; font-size: var(--text-sm); cursor: pointer; }
.chip[aria-pressed="true"] { border-color: var(--foreground); background: var(--foreground); color: var(--background); }
.chip:focus-visible, .size:focus-visible, .pill:focus-visible { outline: var(--focus-outline-width, 2px) solid var(--focus-outline, var(--accent)); outline-offset: 2px; }
