.photo { position: relative; overflow: hidden; border-radius: var(--radius-panel); background: var(--surface-muted); }
.img { display: block; width: 100%; }
.photoHover { position: absolute; inset: 0; opacity: 0; transition: opacity var(--duration-standard, .24s) var(--ease-standard); }
.card:hover .photoHover, .card:focus-within .photoHover { opacity: 1; }
.badge { position: absolute; top: var(--space-2); left: var(--space-2); z-index: 1; padding: 2px; border-radius: var(--radius-pill); background: color-mix(in oklch, var(--surface) 90%, transparent); backdrop-filter: blur(6px); }
