.card:hover .quick, .card:focus-within .quick, .quick[data-open] { transform: none; opacity: 1; }
@media (hover: none) { .quick { transform: none; opacity: 1; } }
.pill, .size { min-height: 2.25rem; padding: 0 var(--space-4); border: 1px solid var(--border); border-radius: var(--radius-pill); background: color-mix(in oklch, var(--surface) 82%, transparent); backdrop-filter: blur(8px); color: var(--foreground); font: inherit; font-size: var(--text-sm); cursor: pointer; }
.pill:disabled { cursor: not-allowed; color: var(--text-muted); }
